export async function listTools() {
  return [
    {
      name: 'format_value',
      description: 'Format a value as text (uppercased) or integer (parsed base-10).',
      inputSchema: {
        type: 'object',
        properties: {
          value: { type: 'string' },
          kind: { type: 'string', enum: ['text', 'integer'] }
        },
        required: ['value', 'kind'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'format_value') throw new Error('Unknown tool: ' + name);

  // Validate no extra fields
  const allowed = new Set(['value', 'kind']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) throw new Error('Unexpected field: ' + key);
  }

  if (typeof args.value !== 'string') throw new Error('value must be a string');
  if (!allowed.has('value') && args.value === undefined) throw new Error('value is required');
  if (args.value === undefined) throw new Error('value is required');
  if (args.kind === undefined) throw new Error('kind is required');
  if (args.kind !== 'text' && args.kind !== 'integer') throw new Error('kind must be text or integer');

  let text;
  if (args.kind === 'text') {
    text = args.value.toUpperCase();
  } else {
    // integer - parse base-10 integer
    const trimmed = args.value.trim();
    if (!/^-?\d+$/.test(trimmed)) throw new Error('Malformed integer: ' + args.value);
    const n = Number(trimmed);
    if (!Number.isSafeInteger(n)) throw new Error('Integer out of range: ' + args.value);
    text = String(n);
  }

  return { content: [{ type: 'text', text }] };
}
